:15,"age_to":15,"sort_order":15514,"is_active":true},{"id":"187d4286-d17f-5f0d-957c-64a557ac748b","phase":"defence","level":"team","component":"Стандартні положення → комплексний вибір","title":"Навчити відповідно до ситуації обирати спосіб реагування, систему організації захисту, захисну структуру та розподіл функцій і ролей.","description":"Перелік тактичних завдань U6–U15 · U15 · формат 11×11 (10+1)","age_from":15,"age_to":15,"sort_order":15515,"is_active":true},{"id":"c58dd75a-6000-572e-938b-9b1641b056fa","phase":"defence","level":"team","component":"Командна тактика захисту → адаптивний вибір","title":"Навчити відповідно до розвитку гри обирати рішення у переході, організацію захисної структури, висоту блоку, спосіб пресингу, систему захисту та рішення під час стандартних положень.","description":"Перелік тактичних завдань U6–U15 · U15 · формат 11×11 (10+1)","age_from":15,"age_to":15,"sort_order":15516,"is_active":true}]$champion_tasks$::jsonb) as x(
    id uuid,
    phase public.methodology_phase,
    level public.methodology_level,
    component text,
    title text,
    description text,
    age_from smallint,
    age_to smallint,
    sort_order integer,
    is_active boolean
  )
)
insert into public.methodology_tasks
  (id, phase, level, component, title, description, age_from, age_to, sort_order, is_active)
select id, phase, level, component, title, description, age_from, age_to, sort_order, is_active
from source
on conflict (id) do update set
  phase = excluded.phase,
  level = excluded.level,
  component = excluded.component,
  title = excluded.title,
  description = excluded.description,
  age_from = excluded.age_from,
  age_to = excluded.age_to,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active,
  updated_at = now();

with source as (
  select *
  from jsonb_to_recordset($champion_terms$[{"id":"9d1a716c-31aa-5e84-904f-094b400e9495","term":"Тактика футболу","definition":"Система індивідуальних, групових і командних тактичних рішень, спрямованих на вирішення ігрових завдань і досягнення мети гри.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Football tactics","is_active":true},{"id":"5b367ee5-0be5-5e95-9f36-9e414d468cd1","term":"Індивідуальна тактика","definition":"Тактичні рішення окремого футболіста в конкретній ігровій ситуації. Головне питання для тренера: яке рішення має прийняти один гравець?","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Individual tactics","is_active":true},{"id":"270c9dc5-251f-5779-bb15-5d80fa0648f0","term":"Групова тактика","definition":"Узгоджені й взаємопов’язані тактичні рішення кількох футболістів для вирішення спільного ігрового завдання. Зазвичай проявляється у взаємодії 2–4 гравців або окремої ланки.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Group tactics / Unit tactics","is_active":true},{"id":"ba650e38-a08f-5366-83e9-eafe134ccbec","term":"Командна тактика","definition":"Система узгоджених командних тактичних рішень і принципів, що визначає організацію гри та взаємодію всієї команди.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Team tactics","is_active":true},{"id":"cb973143-1e99-5be6-835c-5759fe3764f9","term":"Тактика гри","definition":"Конкретна реалізація індивідуальних, групових і командних рішень у матчі відповідно до завдань, суперника, можливостей команди та розвитку гри.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Match tactics / Game tactics","is_active":true},{"id":"bc2dfff8-0f06-5fe5-a71e-45af298ae588","term":"Тактика нападу","definition":"Тактичні рішення команди та футболістів під час володіння м’ячем і після його заволодіння, спрямовані на розвиток атаки та створення гольової можливості.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Attacking tactics / In-possession tactics","is_active":true},{"id":"a693a6c2-9b96-575b-9f49-9e1b187c17b1","term":"Тактика захисту","definition":"Тактичні рішення команди та футболістів після втрати м’яча і під час гри без м’яча, спрямовані на обмеження атаки суперника, захист воріт і повернення володіння.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Defensive tactics / Out-of-possession tactics","is_active":true},{"id":"c6199dae-093a-5201-9ba2-0bcce82fd02b","term":"Схема гри / вихідна розстановка","definition":"Вихідне номінальне розташування футболістів, наприклад 4–3–3 або 4–2–3–1. Схема не дорівнює атакувальній чи захисній структурі: структура динамічно змінюється під час гри.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Formation / Starting formation","is_active":true},{"id":"abfdd59f-46e5-56b1-abb0-e5fdcf3d69fe","term":"Атакувальна структура","definition":"Просторове та взаємне розташування футболістів команди під час володіння м’ячем.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Attacking shape / In-possession structure","is_active":true},{"id":"ae8df45f-6b4e-5358-a3f8-d85f04689c82","term":"Захисна структура","definition":"Просторове та взаємне розташування футболістів команди під час гри без м’яча.","category":"Загальні поняття","source":"Словник тактичних термінів футболу · Defensive shape / Out-of-possession structure","is_active":true},{"id":"164dd024-811f-511c-8535-3f1bf20287ff","term":"Ігрове положення","definition":"Тактичне рішення футболіста щодо вибору просторового розташування та орієнтації корпусу з урахуванням м’яча, партнерів, суперників, воріт, доступного простору і передбачуваного продовження гри.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · Positioning","is_active":true},{"id":"435785b4-fea0-5067-923d-8aabf2999e6a","term":"Орієнтація корпусу","definition":"Положення корпусу футболіста, яке визначає, що він може одночасно бачити та в якому напрямку здатний швидко продовжити гру. Може бути більш відкритим або закритим відповідно до ситуації.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · Body orientation / Body shape","is_active":true},{"id":"f5f72773-56d7-5a7b-8593-570bd4c43006","term":"Зупинка м’яча","definition":"Тактичне рішення щодо доцільності, ступеня та напрямку керованого зменшення швидкості м’яча першим контактом для створення умов наступної дії. У тренерській англійській часто використовується термін first touch.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · First touch / Ball control","is_active":true},{"id":"175da9de-f8c2-58e4-a750-2e51362b1183","term":"Захист м’яча тілом","definition":"Використання положення та переміщення тіла між суперником і м’ячем, щоб обмежити доступ суперника, зберегти володіння та виграти умови для продовження гри.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · Ball shielding / Shielding the ball","is_active":true},{"id":"b548caf1-4e82-57a0-a3cf-dcc04018c41d","term":"Ведення м’яча","definition":"Самостійне переміщення м’яча у просторі з вибором моменту, напрямку та швидкості відповідно до ігрового завдання. У нашій термінології ball carrying відрізняємо від take-on: безпосереднє подолання суперника — це вже обведення.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · Ball carrying","is_active":true},{"id":"528a0088-7128-5cd3-b9f5-5ec81af4d51a","term":"Удаваний рух","definition":"Демонстрація наміру виконати одну дію, щоб викликати реакцію суперника і використати цю реакцію для іншої дії.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · Feint / Dummy action","is_active":true},{"id":"e2c6ce5c-8da7-52ee-8210-b7e841598435","term":"Обведення суперника","definition":"Тактичне рішення футболіста з м’ячем вступити у безпосередню протидію та подолати суперника, щоб зберегти володіння, просунутися, створити передачу або удар.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · Take-on / Dribbling past an opponent","is_active":true},{"id":"2c7de145-7407-593a-8bb6-fe0a78ea361c","term":"Удар по воротах","definition":"Тактичне рішення завершити ігрову ситуацію спробою забити гол, обираючи момент удару, цільову зону воріт і доцільний спосіб виконання.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · Shooting / Shot","is_active":true},{"id":"a36fa7e3-fbf6-5b73-ba53-96bce5a07561","term":"Підключення до атаки","definition":"Рішення футболіста збільшити свою безпосередню участь в атаці, переходячи у більш активну атакувальну позицію або зону з м’ячем чи без м’яча.","category":"Індивідуальна тактика нападу","source":"Словник тактичних термінів футболу · Joining the attack / Attacking run","is_active":true},{"id":"56f91781-f5f0-58a1-8009-463c6b937893","term":"Відкривання","definition":"Узгоджене рішення футболіста без м’яча та партнера з м’ячем щодо вибору або зміни розташування для отримання передачі, створення простору чи впливу на захисну структуру суперника.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Off-the-ball movement / Movement to receive","is_active":true},{"id":"dd69232b-c0e8-5c8a-ab1e-3f523f197f03","term":"Передача м’яча","definition":"Узгоджені рішення партнерів щодо моменту, напрямку, адресування та умов переміщення м’яча від одного футболіста до іншого або у доступний йому простір.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Passing / Pass","is_active":true},{"id":"fb799955-ba7e-59eb-92e0-73d94e65d478","term":"Боротьба за перший м’яч","definition":"Узгоджені рішення партнерів щодо того, хто вступає у перший контакт після доставки м’яча, як розташовуються партнери та куди має бути спрямований м’яч.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · First-ball contest / First-ball duel","is_active":true},{"id":"a3cd1487-09ae-5d59-b2ba-e2269ab724a0","term":"Другий м’яч","definition":"М’яч, який після першого контакту або єдиноборства не переходить під стійкий контроль жодної команди й стає предметом наступного оволодіння.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Second ball","is_active":true},{"id":"6403c1f4-03bb-5a09-8a1d-f96659370c05","term":"Підбирання / боротьба за другий м’яч","definition":"Узгоджені рішення партнерів щодо розташування та готовності оволодіти другим м’ячем для збереження або продовження атаки.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Second-ball recovery / Second-ball contest","is_active":true},{"id":"8d27936c-04eb-57a9-b96e-0c0041836de5","term":"Екранування суперника","definition":"Групова взаємодія, за якої футболіст займає або зберігає дозволену позицію, що ускладнює супернику переміщення до партнера чи простору і створює партнеру сприятливі умови.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Screening / Legal screening","is_active":true},{"id":"efd61772-9a2b-5ec6-a65d-de4325bf821e","term":"Комбінація","definition":"Узгоджена взаємодія двох або більше партнерів на основі взаємопов’язаних тактичних рішень для вирішення спільного ігрового завдання.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Combination play","is_active":true},{"id":"7688aae5-56ba-5209-ad25-dafbb4e5053e","term":"Стінка","definition":"Комбінація двох футболістів: перший виконує передачу партнеру, продовжує переміщення та отримує повернення м’яча для подолання протидії.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · One-two / Wall pass","is_active":true},{"id":"6e4f9ed0-5b2b-577b-8467-054f18726076","term":"Гра на третього","definition":"Комбінація, у якій продовження атаки здійснюється через третього футболіста, коли пряма взаємодія між двома партнерами обмежена суперником.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Third-man combination / Third-player combination","is_active":true},{"id":"6f481a77-93c3-5500-b321-03dac476d355","term":"Взаємозміна позицій","definition":"Узгоджена зміна позицій партнерами зі збереженням можливостей для подальшої взаємодії та просторової організації атаки.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Positional interchange / Rotation","is_active":true},{"id":"63b62e02-866b-5638-8367-219cdf24fe74","term":"Позиційна підтримка атаки","definition":"Вибір, збереження та корекція взаємного розташування кількох футболістів відносно гравця з м’ячем для створення доступних варіантів продовження атаки.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Positional support / Support play","is_active":true},{"id":"2cfc9f4d-e79f-5475-b60b-0465c7ee1f2f","term":"Створення чисельної переваги","definition":"Узгоджене переміщення та концентрація додаткових футболістів у визначеній зоні для створення локальної переваги, наприклад 2×1 або 3×2.","category":"Групова тактика нападу","source":"Словник тактичних термінів футболу · Creating numerical superiority / Numerical advantage","is_active":true},{"id":"1c327dab-d0fc-5d6d-bc2d-665f28b0a25e","term":"Перехід від захисту до нападу","definition":"Ситуація безпосередньо після заволодіння м’ячем, у якій команда визначає, чи використати тимчасову неорганізованість суперника, чи перейти до контрольованого володіння.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Attacking transition / Transition to attack","is_active":true},{"id":"3486d954-958a-5363-8868-190e3a94b594","term":"Контратака","definition":"Рішення після заволодіння м’ячем негайно використати тимчасову неорганізованість суперника та вільний простір для швидкого розвитку атаки. Контратака належить саме до переходу.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Counter-attack","is_active":true},{"id":"cd620a31-6813-5f5c-95e3-f74d2d610a2b","term":"Збереження володіння та формування атакувальної структури","definition":"Рішення після заволодіння м’ячем не форсувати контратаку, а зберегти контроль і сформувати структуру для організованого нападу.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Retain possession and establish attacking shape","is_active":true},{"id":"8e04fc46-9dd0-50eb-b629-01b7d8471362","term":"Початок атаки","definition":"Етап організованої атаки, на якому команда встановлює контроль і створює умови для подолання початкового тиску суперника та подальшого просування.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Build-up","is_active":true},{"id":"8d60267d-85a2-58a7-b905-7fbb6a439072","term":"Просування м’яча","definition":"Розвиток атаки з переміщенням м’яча та команди у напрямку воріт суперника через передачі, ведення і взаємодії.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Ball progression / Progression","is_active":true},{"id":"0322377c-2aab-5ee6-ac79-8b1a4734316b","term":"Завершення атаки","definition":"Етап атаки, на якому команда намагається створити та реалізувати безпосередню гольову можливість.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Finishing phase / Final phase","is_active":true},{"id":"1970c600-663f-5009-956e-c7f71f50033b","term":"Організований напад","definition":"Напад в умовах контрольованого володіння та сформованої або такої, що формується, атакувальної структури.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Organised attack","is_active":true},{"id":"f2f7e3ee-c4d5-5e54-897c-9891bc802ede","term":"Організація атакувальної структури","definition":"Командні рішення щодо просторового та взаємного розташування футболістів під час володіння м’ячем.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Attacking organisation / Organisation of attacking shape","is_active":true},{"id":"16d8e129-b390-5856-9f20-85b57da08f6b","term":"Ширина","definition":"Розподіл футболістів по ширині поля для розтягування захисної структури суперника та створення просторів для розвитку атаки.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Width","is_active":true},{"id":"c2dda6d1-f40e-5a93-87a2-cfa4e890a6d9","term":"Глибина","definition":"Розташування футболістів на різних вертикальних рівнях відносно м’яча для створення варіантів гри вперед, назад і за лінії суперника.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Depth","is_active":true},{"id":"ab833f51-c001-55d4-a65c-6ee0d208f5d2","term":"Розподіл футболістів по зонах і лініях","definition":"Рішення щодо того, які просторові зони й позиційні рівні займають футболісти, щоб забезпечити ширину, глибину, зв’язки та варіанти продовження атаки.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Occupation of zones and lines / Positional occupation","is_active":true},{"id":"60ef1a32-5caf-5714-a5c0-2ff92168a3cf","term":"Перебудова атакувальної структури","definition":"Узгоджена зміна розташування команди відповідно до переміщення м’яча, переходу між етапами атаки та поведінки суперника.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Attacking shape adjustment / Restructuring","is_active":true},{"id":"70827b3b-0e4c-5825-8535-21729df6aa7e","term":"Баланс атакувальної структури","definition":"Розташування частини футболістів під час власної атаки так, щоб команда зберігала контроль простору й була готова до можливої втрати м’яча.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Rest defence / Attacking balance","is_active":true},{"id":"9921b9a0-b43c-5b92-b2c7-c563c65f6f36","term":"Позиційна атака","definition":"Вид організованої атаки, у якому команда послідовно розвиває гру проти сформованого захисту, використовуючи структуру, простір і взаємодії для створення переваги.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Positional attack","is_active":true},{"id":"94c00603-3da2-56bc-acb5-38e18f7787da","term":"Швидка атака","definition":"Вид організованої атаки, у якому команда за сприятливих умов швидко доставляє м’яч у зону завершення з мінімально необхідною кількістю дій. Не є синонімом контратаки: швидка атака може відбуватися вже в організованому нападі.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Fast attack / Quick attack","is_active":true},{"id":"ed8716ad-db6f-55f8-b7d6-bcede2c939b7","term":"Напрям розвитку атаки","definition":"Командне рішення щодо просторового коридору, через який розвивається атака: центр, напівфланг або фланг.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Attacking route / Direction of attack","is_active":true},{"id":"d9d79e1c-2403-507a-b399-dcc7660044f7","term":"Центр","definition":"Центральний вертикальний коридор поля, через який команда може розвивати атаку.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Central channel","is_active":true},{"id":"1a5c5c32-e241-5d46-af25-3970453dc5df","term":"Напівфланг","definition":"Вертикальний коридор між центральною і фланговою зонами поля. Часто використовується для отримання м’яча між лініями та створення кутів передачі.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Half-space","is_active":true},{"id":"78bbf8d5-40e1-5152-b734-2ad255e7d30b","term":"Фланг","definition":"Широка зовнішня зона поля біля бокової лінії, через яку команда може розвивати атаку в обхід центральної захисної структури.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Wide channel / Flank","is_active":true},{"id":"bb40c3c3-4272-5ea4-a0cb-d1a463403fbe","term":"Перевантаження","definition":"Створення локальної чисельної або позиційної переваги шляхом концентрації додаткових футболістів у визначеній зоні.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Overload","is_active":true},{"id":"e6c458e9-bb21-5d6e-a4ea-30d3234726a6","term":"Ізоляція","definition":"Створення умов, у яких обраний футболіст отримує сприятливе протистояння, найчастіше 1×1, у визначеному просторі.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Isolation","is_active":true},{"id":"688e4501-c85c-59e1-8a87-a6e3f93febba","term":"Зміна напрямку атаки","definition":"Перенесення розвитку атаки із зони, де суперник сконцентрував захист, у іншу, менш захищену зону.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Switch of play / Switching play","is_active":true},{"id":"66ea7c6d-27cd-509e-a9d8-4c2473dae3ce","term":"Зміна темпу атаки","definition":"Свідоме прискорення або уповільнення розвитку атаки для зміни поведінки захисту та використання створеного простору.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Change of tempo / Tempo variation","is_active":true},{"id":"4b2293f5-9075-5b33-8d77-cd3bb3590347","term":"Цільовий гравець","definition":"Футболіст, якого команда використовує як визначену опорну точку для доставки, збереження, скидки або продовження м’яча.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Target player","is_active":true},{"id":"2b170ea1-7f60-5041-9ff1-18ab7334de6d","term":"Гра через цільового гравця","definition":"Командний механізм розвитку атаки через передачу на цільового футболіста з подальшим збереженням, скидкою, грою на третього або створенням простору.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Playing through a target player","is_active":true},{"id":"6a4fcd04-18e0-58ff-bef9-2d71637b7acb","term":"Подолання захисної структури","definition":"Командне рішення щодо просторового шляху просування м’яча відносно структури суперника.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Breaking / Bypassing the defensive structure","is_active":true},{"id":"21b5ceab-8582-59b8-b0ed-fb1311b9130a","term":"Крізь захисну структуру","definition":"Просування м’яча між футболістами або лініями суперника через внутрішні проміжки структури.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Play through the defensive structure","is_active":true},{"id":"0e6398ca-1f2f-5b0b-ab0d-ce6a4699ae52","term":"В обхід захисної структури","definition":"Просування м’яча зовнішнім шляхом, переважно через ширину або фланг, з обходом компактної частини захисту.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Play around the defensive structure","is_active":true},{"id":"5a640d10-57fc-5d9d-949a-6bad4ba04cd4","term":"Над захисною структурою","definition":"Просування м’яча передачею над однією або кількома лініями суперника у вільний простір або до партнера.","category":"Командна тактика нападу","source":"Словник тактичних термінів футболу · Play over the defensive structure","is_active":true},{"id":"f052cf2b-4438-5509-9df3-eed791128e96","term":"Стандартне положення","definition":"Поновлення гри за встановленою правилами процедурою. У нашій класифікації стандарти належать до командної тактики, оскільки потребують організації розташування, взаємодій і ролей.","category":"Стандартні положення в нападі","source":"Словник тактичних термінів футболу · Set play / Set piece","is_active":true},{"id":"502b542c-4393-576e-b518-a65367f8de29","term":"Швидкий розіграш","definition":"Поновлення гри до повної організації захисної структури суперника з метою використати тимчасово відкритий простір або неготовність захисту.","category":"Стандартні положення в нападі","source":"Словник тактичних термінів футболу · Quick restart","is_active":true},{"id":"717c9aaa-d81f-5980-85bd-055c4ab06258","term":"Організований розіграш","definition":"Поновлення гри після попереднього розташування футболістів і визначення принципу взаємодії.","category":"Стандартні положення в нападі","source":"Словник тактичних термінів футболу · Organised restart / Organised set play","is_active":true},{"id":"5f4d1df1-50b8-582a-bb20-212aedbd9a04","term":"Тактичне призначення стандарту","definition":"Ігрове завдання стандарту: зберегти володіння, просунути м’яч, проникнути за структуру, створити гольову можливість або безпосередньо завершити атаку.","category":"Стандартні положення в нападі","source":"Словник тактичних термінів футболу · Set-play tactical objective","is_active":true},{"id":"360125b7-12f2-5533-af1d-b27688ebbccf","term":"Атакувальна структура при стандарті","definition":"Розташування виконавця, адресатів, футболістів для створення простору, боротьби за перший і другий м’яч та забезпечення балансу.","category":"Стандартні положення в нападі","source":"Словник тактичних термінів футболу · Attacking set-piece structure","is_active":true},{"id":"074fcb5f-9cd4-5f44-a7ea-dc53eb340ac9","term":"Розподіл функцій і ролей при стандарті","definition":"Попереднє або ситуативне визначення відповідальності футболістів: виконавець, адресат, гравці для створення простору, першого і другого м’яча, продовження атаки та балансу.","category":"Стандартні положення в нападі","source":"Словник тактичних термінів футболу · Set-play role allocation","is_active":true},{"id":"e4203dd3-666d-56a3-b089-be01757fb369","term":"Ігрове положення в захисті","definition":"Вибір просторового розташування, дистанції та орієнтації корпусу з урахуванням м’яча, суперника, партнерів, власних воріт і небезпечного простору.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Defensive positioning","is_active":true},{"id":"75892e08-94b9-518e-9d6c-a8a0595e21b7","term":"Сповільнення просування суперника","definition":"Рішення не вступати негайно у відбирання, а обмежити швидкість просування суперника й виграти час для відновлення захисної організації.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Delay / Delaying the attacker","is_active":true},{"id":"baaed410-3c1b-5906-8424-b03e1fd7e550","term":"Спрямування суперника","definition":"Вплив на напрямок руху суперника з м’ячем так, щоб залишити йому менш сприятливий варіант: назовні, усередину, назад, на слабшу сторону або в підготовлену зону тиску.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Showing / Steering / Forcing the opponent","is_active":true},{"id":"26f9e8c6-894a-591b-a3bc-7da352198c6e","term":"Опіка суперника","definition":"Контроль положення та переміщення конкретного суперника з метою обмежити можливість отримання м’яча, продовження гри або входу в небезпечний простір.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Marking","is_active":true},{"id":"9ebe290e-0381-5891-a166-d1cbd39523c5","term":"Боротьба за м’яч","definition":"Рішення вступити у безпосереднє єдиноборство за м’яч, який не перебуває під стійким контролем жодного гравця, з метою оволодіти ним або спрямувати у вигідний чи безпечний простір.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Ball contest / Duel for the ball","is_active":true},{"id":"892b30c2-feb2-550f-9eb0-b57754a7fb8c","term":"Перекривання","definition":"Позиційне рішення зайняти положення, яке ускладнює або виключає певну лінію передачі чи удару. Під час тиску може виконуватися пресинговою тінню.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Screening / Denying passing or shooting lanes","is_active":true},{"id":"2ad251eb-a017-5bc2-88bf-e31c341b1bb6","term":"Відбирання м’яча","definition":"Безпосередня дія проти м’яча, який контролює суперник, з метою припинити його контроль: з оволодінням або вибиванням.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Tackling / Winning the ball","is_active":true},{"id":"e6de82ff-a0ab-57c7-97b7-1be82d4e9b72","term":"Перехоплення м’яча","definition":"Рішення випередити передачу суперника та оволодіти м’ячем до того, як його отримає передбачуваний адресат.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Interception","is_active":true},{"id":"ed2618e7-018b-51dc-90c1-bd144620466b","term":"Блокування","definition":"Безпосереднє переривання або зміна траєкторії м’яча під час уже виконуваної суперником передачі чи удару.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Blocking","is_active":true},{"id":"3b2eccec-be35-5c79-89d3-e21493839044","term":"Винесення м’яча","definition":"Рішення в умовах безпосередньої загрози відмовитися від збереження контрольованого володіння й спрямувати м’яч із небезпечної зони.","category":"Індивідуальна тактика захисту","source":"Словник тактичних термінів футболу · Clearance","is_active":true},{"id":"64355209-e907-5a8f-ab30-378167686949","term":"Підстраховка","definition":"Рішення партнера зайняти положення відносно футболіста, який безпосередньо протидіє супернику, щоб своєчасно вступити в дію у випадку його обіграшу або зміни ситуації.","category":"Групова тактика захисту","source":"Словник тактичних термінів футболу · Cover / Defensive cover","is_active":true},{"id":"eed17f28-b5a8-54e6-9efe-c72f5d1f9a82","term":"Переключення опіки","definition":"Узгоджене рішення захисників передати контроль над суперником партнеру та, за потреби, прийняти під контроль іншого суперника під час переміщень.","category":"Групова тактика захисту","source":"Словник тактичних термінів футболу · Switching marking / Passing on an opponent","is_active":true},{"id":"9ab1dffd-47f2-573e-b253-877de8907f05","term":"Розподіл опіки","definition":"Узгоджене визначення, хто з партнерів контролює конкретних суперників у даній ситуації, з можливістю ситуаційного перерозподілу.","category":"Групова тактика захисту","source":"Словник тактичних термінів футболу · Marking assignment / Allocation of marking responsibilities","is_active":true},{"id":"f084a1cf-49f3-5e0c-8eb5-2b10787ff96f","term":"Подвоєння","definition":"Одночасна активна протидія двох захисників одному супернику з м’ячем для створення локальної чисельної переваги. На відміну від підстраховки, другий захисник уже активно вступає в протидію.","category":"Групова тактика захисту","source":"Словник тактичних термінів футболу · Double-team / Doubling up","is_active":true},{"id":"8c445f91-f013-56e0-9a62-b4f36d4126f4","term":"Компенсація позицій","definition":"Зайняття партнером простору або позиції, яку залишив інший футболіст через активну захисну дію, щоб зберегти структуру та не допустити небезпечного вільного простору.","category":"Групова тактика захисту","source":"Словник тактичних термінів футболу · Defensive rotation / Positional cover","is_active":true},{"id":"06ea53d2-c3f4-5378-acd4-39590be25cf4","term":"Координоване переміщення захисної ланки","definition":"Спільна зміна взаємного розташування гравців однієї ланки відповідно до руху м’яча, суперників і партнерів для збереження компактності, підтримки та цілісності.","category":"Групова тактика захисту","source":"Словник тактичних термінів футболу · Coordinated movement of the defensive unit","is_active":true},{"id":"4dfdaaf6-a7ed-56f2-beab-737ce4d2cf54","term":"Створення офсайдної пастки","definition":"Синхронна зміна положення останньої захисної лінії з метою залишити суперника в положенні «поза грою» у момент можливої передачі. Потребує повної синхронності лінії.","category":"Групова тактика захисту","source":"Словник тактичних термінів футболу · Offside trap","is_active":true},{"id":"620e01f0-05ba-5cb2-b60f-014cf4b4f49b","term":"Перехід від нападу до захисту","definition":"Ситуація безпосередньо після втрати м’яча, у якій команда визначає спосіб переходу до захисту.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Defensive transition / Transition to defend","is_active":true},{"id":"011136e8-ecd1-522f-ab13-de34c91651cd","term":"Контрпресинг","definition":"Негайна колективна спроба після втрати м’яча створити тиск навколо зони втрати та повернути володіння або не дозволити супернику швидко розвинути атаку.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Counter-pressing / Counter-press","is_active":true},{"id":"e68967c5-3a4a-50a8-85e1-2f700b3b5c13","term":"Стримування суперника та відновлення захисної структури","definition":"Рішення після втрати не форсувати негайне повернення м’яча, а сповільнити суперника й відновити організовану захисну структуру.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Delay and recover defensive shape","is_active":true},{"id":"84a278fa-0326-5859-aff9-50b5a13e64e0","term":"Організований захист","definition":"Захист команди в умовах сформованої або такої, що формується, захисної структури.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Organised defence","is_active":true},{"id":"5f4453c0-08df-5d4e-9a84-32823598b26d","term":"Організація захисної структури","definition":"Командні рішення щодо конфігурації ліній, взаємного розташування, відстаней і перебудови команди під час гри без м’яча.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Defensive organisation / Organisation of defensive shape","is_active":true},{"id":"babde03a-b9c4-5425-a156-a6bce969881e","term":"Компактність","definition":"Здатність команди або ланки підтримувати доцільно малі відстані між гравцями та лініями, щоб обмежувати простір для гри суперника крізь структуру.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Compactness","is_active":true},{"id":"d1ac3cb9-458e-514d-8fc9-959ffbb995da","term":"Висота захисного блоку","definition":"Командне рішення щодо висоти поля, на якій команда формує організований захист.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Block height","is_active":true},{"id":"4ad02eb3-df4e-5b2f-a393-b0069a1843ef","term":"Високий блок","definition":"Організована захисна позиція команди високо на полі, близько до воріт або початку атаки суперника.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · High block","is_active":true},{"id":"d9755902-5d7c-578b-a28d-f18c18eb3d65","term":"Середній блок","definition":"Організована компактна захисна структура переважно в середній частині поля.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Mid-block","is_active":true},{"id":"6c5ce948-4b13-59c5-9c78-31ec9d3563da","term":"Низький блок","definition":"Організована компактна захисна структура глибоко на власній половині поля, поблизу власних воріт.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Low block","is_active":true},{"id":"e2062329-7501-5320-b051-1b68b3370365","term":"Пресинг","definition":"Активний узгоджений тиск на суперника з метою обмежити його час і простір, спрямувати розвиток гри та створити умови для повернення м’яча.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Pressing / Press","is_active":true},{"id":"3c8646c5-63fb-54a2-8373-cdd40f0b7dc0","term":"Організація пресингу","definition":"Командні рішення щодо моменту початку, напрямку та координації колективного тиску.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Pressing organisation / Pressing structure","is_active":true},{"id":"547f6aa1-dd74-50ae-a0c6-e91ebd5838da","term":"Пресинговий тригер","definition":"Попередньо визначена або ситуативно розпізнана дія суперника, яка є сигналом для початку або посилення колективного пресингу.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Pressing trigger","is_active":true},{"id":"50e1bea2-3dc4-5153-a4a2-cbcc9be71e67","term":"Напрямок пресингу","definition":"Рішення команди, у який простір спрямовувати суперника під час тиску, одночасно закриваючи небажані варіанти продовження.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Pressing direction / Forcing direction","is_active":true},{"id":"d0ae3cd8-6116-5df2-a8fe-2c0708b36c9f","term":"Координація командного пресингу","definition":"Синхронізація дій першого футболіста, який тисне на м’яч, та партнерів, які підтримують пресинг, перекривають передачі й переміщують лінії.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Coordinated team press / Pressing coordination","is_active":true},{"id":"f37fabae-a196-5b5d-9fac-cbf83775cc45","term":"Система організації захисту","definition":"Командне рішення щодо основних орієнтирів, за якими футболісти організовують свої позиції та взаємодії без м’яча.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Defensive organisation system / Defensive marking system","is_active":true},{"id":"f13dbafe-9245-57d6-aeea-63c0d98a5d46","term":"Зонна система захисту","definition":"Організація захисту з пріоритетом контролю визначених зон і простору, а не постійного супроводу конкретного суперника.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Zonal defending / Zonal marking","is_active":true},{"id":"f19b9fd8-827f-53f5-bac4-6e21517d9a2b","term":"Персонально орієнтована система захисту","definition":"Організація, у якій футболісти значною мірою коригують позиції відносно конкретних суперників, зберігаючи загальну командну структуру.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Man-oriented defending / Player-oriented marking","is_active":true},{"id":"2b7e2fc3-cccf-58b7-b456-ced4d8e36eb9","term":"Комбінована система захисту","definition":"Поєднання зонних і персонально орієнтованих принципів у межах однієї захисної організації.","category":"Командна тактика захисту","source":"Словник тактичних термінів футболу · Hybrid defending / Hybrid marking","is_active":true},{"id":"fcafdf9d-3d73-508d-a145-2df7d82aab7f","term":"Захист стандартних положень","definition":"Система командних рішень під час поновлення гри суперником, що визначає спосіб реагування, структуру, систему захисту та взаємодію футболістів.","category":"Стандартні положення в захисті","source":"Словник тактичних термінів футболу · Set-piece defending / Defending set plays","is_active":true},{"id":"20ca336c-862f-5364-a05a-248b0c26421b","term":"Спосіб реагування на поновлення гри","definition":"Рішення щодо організації захисту залежно від того, чи суперник поновлює гру швидко, чи після підготовленого розіграшу.","category":"Стандартні положення в захисті","source":"Словник тактичних термінів футболу · Restart response / Defensive response to restart","is_active":true},{"id":"b6bf52ea-ff51-56be-96b3-cd49d1983996","term":"Система захисту при стандартному положенні","definition":"Вибір основних орієнтирів відповідальності при стандарті: зонних, персонально орієнтованих або комбінованих.","category":"Стандартні положення в захисті","source":"Словник тактичних термінів футболу · Set-piece marking system","is_active":true},{"id":"a870c756-e68f-5ca9-9c99-16efa46a9d1b","term":"Зонний захист при стандарті","definition":"Футболісти відповідають насамперед за визначені зони й м’яч, реагуючи на суперників, які входять у ці зони.","category":"Стандартні положення в захисті","source":"Словник тактичних термінів футболу · Zonal set-piece defending / Zonal marking","is_active":true},{"id":"87ebc1d9-5c2d-54f9-b8c8-7d797e124d7d","term":"Персонально орієнтований захист при стандарті","definition":"Футболісти отримують відповідальність за конкретних суперників і контролюють їхні переміщення під час виконання стандарту.","category":"Стандартні положення в захисті","source":"Словник тактичних термінів футболу · Man-oriented set-piece defending / Man marking","is_active":true},{"id":"492e3fc9-6223-592d-9721-ba55ba53e93d","term":"Комбінований захист при стандарті","definition":"Поєднання зонних функцій частини футболістів із персональним контролем визначених суперників.","category":"Стандартні положення в захисті","source":"Словник тактичних термінів футболу · Hybrid set-piece defending / Hybrid marking","is_active":true},{"id":"1c8c6585-9b9d-577c-a5ca-30d8b97a7080","term":"Захисна структура при стандарті","definition":"Просторове розташування футболістів відносно м’яча, воріт, суперників і зон загрози, включно зі стінкою, захистом першого й другого м’яча та готовністю до переходу.","category":"Стандартні положення в захисті","source":"Словник тактичних термінів футболу · Defensive set-piece structure","is_active":true},{"id":"972fd9b5-56ff-5d4e-a556-4b7b95c804ac","term":"Розподіл функцій і ролей при стандарті","definition":"Визначення відповідальності воротаря, футболістів у стінці, зонних і персональних захисників, гравців першого/другого м’яча та футболістів для можливого переходу в напад.","category":"Стандартні положення в захисті","source":"Словник тактичних термінів футболу · Defensive set-play role allocation","is_active":true}]$champion_terms$::jsonb) as x(
    id uuid,
    term text,
    definition text,
    category text,
    source text,
    is_active boolean
  )
)
insert into public.terminology_entries
  (id, term, definition, category, source, is_active)
select id, term, definition, category, source, is_active
from source
on conflict (term, category) do update set
  definition = excluded.definition,
  category = excluded.category,
  source = excluded.source,
  is_active = excluded.is_active,
  updated_at = now();

commit;
